30	/**
31	 * Simple JavaBean domain object representing an owner.
32	 *
33	 * @author Ken Krebs
34	 * @author Juergen Hoeller
35	 * @author Sam Brannen
36	 * @author Michael Isvy
37	 */
38	@Entity
39	@Table(name = "owners")
40	public class Owner extends Person {
41	    @Column(name = "address")
42	    @NotEmpty
43	    private String address;
44	
45	    @Column(name = "city")
46	    @NotEmpty
47	    private String city;
48	
49	    @Column(name = "telephone")
50	    @NotEmpty
51	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form (a leading '+' and 8 to 15 digits)")
52	    private String telephone;
53	
54	    @Column(name = "email")
55	    @Email
56	    private String email;
57	
58	    @Column(name = "registration_date")
59	    private LocalDate registrationDate;
60	
61	    @Column(name = "birth_date")
62	    private LocalDate birthDate;
63	
64	    @Column(name = "customer_code")
65	    private String customerCode;
66	
67	    @Column(name = "household_id")
68	    private String householdId;
69	
70	    @Column(name = "namesake_count")
71	    private Integer namesakeCount;
72	
73	    @Column(name = "postcode")
74	    private String postcode;
75	
76	    /**
77	     * Whether this owner was flagged as a suspected soft-duplicate of an existing owner. Retained
78	     * as part of the API/persistence contract but always {@code false} under the current
79	     * household-keyed rule: an owner sharing an existing owner's {@code lastName} and
80	     * {@code postcode} is now the same household, so it is either rejected as a household duplicate
81	     * (409) or admitted as a declared {@code sharesHousehold} member — and a declared member is not
82	     * a suspected duplicate. No production code path sets this field.
83	     */
84	    @Column(name = "possible_duplicate")
85	    private boolean possibleDuplicate;
86	
87	    /**
88	     * The id of the existing owner this owner soft-matches, set together with
89	     * {@link #isPossibleDuplicate()}. Retained for contract compatibility but always {@code null}
90	     * under the current household-keyed rule (see {@link #isPossibleDuplicate()}); no production
91	     * code path sets it.
92	     */
93	    @Column(name = "possible_duplicate_of")
94	    private Integer possibleDuplicateOf;
95	
96	    /**
97	     * Write-only, non-persistent acknowledgement that this owner deliberately shares a
98	     * household with an existing owner. When {@code true}, creation is allowed even if
99	     * another owner already has the same lastName and address.
100	     */
101	    @Transient
102	    private boolean sharesHousehold;
103	
104	    /**
105	     * Read-only, non-persistent count of the owners that share this owner's {@code householdId}
106	     * (including this owner), populated by the service when an owner is loaded for presentation.
107	     * Zero when the owner belongs to no household. Used to derive the membership tier.
108	     */
109	    @Transient
110	    private int householdSize;
111	
112	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
113	    private Set<Pet> pets;
114	
115	    public String getAddress() {
116	        return this.address;
117	    }
118	
119	    public void setAddress(String address) {
120	        this.address = address;
121	    }
122	
123	    public String getCity() {
124	        return this.city;
125	    }
126	
127	    public void setCity(String city) {
128	        this.city = city;
129	    }
130	
131	    public String getTelephone() {
132	        return this.telephone;
133	    }
134	
135	    public void setTelephone(String telephone) {
136	        this.telephone = telephone;
137	    }
138	
139	    /**
140	     * The stored E.164 {@link #getTelephone() telephone} formatted for human display: the
141	     * country code, a space, then the national digits grouped in threes (e.g.
142	     * {@code "+61 412 345 678"}). Null when no telephone is set.
143	     */
144	    public String getTelephoneDisplay() {
145	        return E164Telephone.toDisplay(this.telephone);
146	    }
147	
148	    public String getEmail() {
149	        return this.email;
150	    }
151	
152	    public void setEmail(String email) {
153	        this.email = email;
154	    }
155	
156	    public LocalDate getRegistrationDate() {
157	        return this.registrationDate;
158	    }
159	
160	    public void setRegistrationDate(LocalDate registrationDate) {
161	        this.registrationDate = registrationDate;
162	    }
163	
164	    public LocalDate getBirthDate() {
165	        return this.birthDate;
166	    }
167	
168	    public void setBirthDate(LocalDate birthDate) {
169	        this.birthDate = birthDate;
170	    }
171	
172	    /**
173	     * The owner's age band derived from {@code birthDate} measured against {@code registrationDate}:
174	     * {@code "MINOR"} when under 18, {@code "ADULT"} from 18 to 64, and {@code "SENIOR"} at 65 or
175	     * over. Returns null when either the birth date or the registration date is not set.
176	     */
177	    public String getAgeBand() {
178	        if (this.birthDate == null || this.registrationDate == null) {
179	            return null;
180	        }
181	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
182	        if (age < 18) {
183	            return "MINOR";
184	        }
185	        if (age < 65) {
186	            return "ADULT";
187	        }
188	        return "SENIOR";
189	    }
190	
191	    public String getCustomerCode() {
192	        return this.customerCode;
193	    }
194	
195	    public void setCustomerCode(String customerCode) {
196	        this.customerCode = customerCode;
197	    }
198	
199	    public String getHouseholdId() {
200	        return this.householdId;
201	    }
202	
203	    public void setHouseholdId(String householdId) {
204	        this.householdId = householdId;
205	    }
206	
207	    public Integer getNamesakeCount() {
208	        return this.namesakeCount;
209	    }
210	
211	    public void setNamesakeCount(Integer namesakeCount) {
212	        this.namesakeCount = namesakeCount;
213	    }
214	
215	    public String getPostcode() {
216	        return this.postcode;
217	    }
218	
219	    public void setPostcode(String postcode) {
220	        this.postcode = postcode;
221	    }
222	
223	    public boolean isPossibleDuplicate() {
224	        return this.possibleDuplicate;
225	    }
226	
227	    public void setPossibleDuplicate(boolean possibleDuplicate) {
228	        this.possibleDuplicate = possibleDuplicate;
229	    }
230	
231	    public Integer getPossibleDuplicateOf() {
232	        return this.possibleDuplicateOf;
233	    }
234	
235	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
236	        this.possibleDuplicateOf = possibleDuplicateOf;
237	    }
238	
239	    /** The highest membership level assignable on creation; level 4 is reserved for tenure. */
240	    public static final int MAX_MEMBERSHIP_LEVEL = 3;
241	
242	    /**
243	     * The owner's numeric membership level, computed from stored fields: it starts at 1, gains 1
244	     * when an email is present, gains 1 when {@code namesakeCount} is 0, and is capped at
245	     * {@value #MAX_MEMBERSHIP_LEVEL} (level 4 is reserved for tenure).
246	     */
247	    public int getMembershipLevel() {
248	        int level = 1;
249	        if (this.email != null && !this.email.isEmpty()) {
250	            level++;
251	        }
252	        if (this.namesakeCount != null && this.namesakeCount == 0) {
253	            level++;
254	        }
255	        return Math.min(level, MAX_MEMBERSHIP_LEVEL);
256	    }
257	
258	    /**
259	     * The derived identity key used to detect duplicate owners: the (already normalized) telephone,
260	     * the email or empty, and the {@code householdId} or empty, joined with {@code '|'}. This single
261	     * key consolidates the former separate telephone, email and household duplicate rules — two
262	     * owners are duplicates only when their whole identity keys are equal. Because the telephone is
263	     * part of the key, two members of the same household (same {@code householdId}) with different
264	     * telephones have different keys and are both allowed.
265	     */
266	    public String getIdentityKey() {
267	        String tel = this.telephone == null ? "" : this.telephone;
268	        String mail = this.email == null ? "" : this.email;
269	        String household = this.householdId == null ? "" : this.householdId;
270	        return tel + "|" + mail + "|" + household;
271	    }
272	
273	    /**
274	     * A single Luhn check digit (0-9) computed over the digits contained in {@code customerCode},
275	     * or null when the {@code customerCode} has not been assigned.
276	     */
277	    public Integer getCheckDigit() {
278	        if (this.customerCode == null) {
279	            return null;
280	        }
281	        int sum = 0;
282	        boolean dbl = true;
283	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
284	            char c = this.customerCode.charAt(i);
285	            if (c < '0' || c > '9') {
286	                continue;
287	            }
288	            int d = c - '0';
289	            if (dbl) {
290	                d *= 2;
291	                if (d > 9) {
292	                    d -= 9;
293	                }
294	            }
295	            sum += d;
296	            dbl = !dbl;
297	        }
298	        return (10 - (sum % 10)) % 10;
299	    }
300	
301	    public boolean isSharesHousehold() {
302	        return this.sharesHousehold;
303	    }
304	
305	    public void setSharesHousehold(boolean sharesHousehold) {
306	        this.sharesHousehold = sharesHousehold;
307	    }
308	
309	    public int getHouseholdSize() {
310	        return this.householdSize;
311	    }
312	
313	    public void setHouseholdSize(int householdSize) {
314	        this.householdSize = householdSize;
315	    }
316	
317	    protected Set<Pet> getPetsInternal() {
318	        if (this.pets == null) {
319	            this.pets = new HashSet<>();
320	        }
321	        return this.pets;
322	    }
323	
324	    protected void setPetsInternal(Set<Pet> pets) {
325	        this.pets = pets;
326	    }
327	
328	    public List<Pet> getPets() {
329	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
330	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
331	        return Collections.unmodifiableList(sortedPets);
332	    }
333	
334	    public void setPets(List<Pet> pets) {
335	        this.pets = new HashSet<>(pets);
336	    }
337	
338	    public void addPet(Pet pet) {
339	        getPetsInternal().add(pet);
340	        pet.setOwner(this);
341	    }
342	
343	    /**
344	     * Return the Pet with the given name, or null if none found for this Owner.
345	     *
346	     * @param name to test
347	     * @return true if pet name is already in use
348	     */
349	    public Pet getPet(String name) {
350	        return getPet(name, false);
351	    }
352	
353	    /**
354	     * Return the Pet with the given name, or null if none found for this Owner.
355	     *
356	     * @param name to test
357	     * @return true if pet name is already in use
358	     */
359	    public Pet getPet(String name, boolean ignoreNew) {
360	        name = name.toLowerCase();
361	        for (Pet pet : getPetsInternal()) {
362	            if (!ignoreNew || !pet.isNew()) {
363	                String compName = pet.getName();
364	                compName = compName.toLowerCase();
365	                if (compName.equals(name)) {
366	                    return pet;
367	                }
368	            }
369	        }
370	        return null;
371	    }
372	
373	    public Pet getPet(Integer petId) {
374	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
375	    }
376	
377	    @Override
378	    public String toString() {
379	        return new ToStringCreator(this)
380	
381	            .append("id", this.getId())
382	            .append("new", this.isNew())
383	            .append("lastName", this.getLastName())
384	            .append("firstName", this.getFirstName())
385	            .append("address", this.address)
386	            .append("city", this.city)
387	            .append("telephone", this.telephone)
388	            .toString();
389	    }
390	}
