250	    /**
251	     * Rejects saving {@code owner} when it carries a postcode that is out of range for its city's
252	     * region. The postcode is optional: a {@code null} postcode is left untouched. When present it
253	     * is assumed to already be four digits (enforced by request validation); if the owner's city has
254	     * a known region (see {@link Region}), the postcode must fall within that region's range
255	     * ({@link Region#postcodeRange(String)}). A city with no known region accepts any 4-digit
256	     * postcode.
257	     *
258	     * @throws InvalidPostcodeException if the postcode is out of range for the city's region
259	     */
260	    private void assertPostcodeValid(Owner owner) {
261	        String postcode = owner.getPostcode();
262	        if (postcode == null) {
263	            return;
264	        }
265	        String region = Region.forCity(owner.getCity());
266	        int[] range = region == null ? null : Region.postcodeRange(region);
267	        if (range == null) {
268	            return;
269	        }
270	        int value = Integer.parseInt(postcode);
271	        if (value < range[0] || value > range[1]) {
272	            throw new InvalidPostcodeException(postcode, owner.getCity(), region);
273	        }
274	    }
275	
276	    /**
277	     * Rejects saving {@code owner} when it carries a {@code registrationDate} later than the current
278	     * server date. The registration date is optional: a {@code null} date is left untouched (it is
279	     * defaulted to today by {@link #saveOwner(Owner)}). A registration cannot be dated in the future.
280	     *
281	     * @throws FutureRegistrationDateException if the supplied registration date is after today
282	     */
283	    private void assertRegistrationDateNotFuture(Owner owner) {
284	        LocalDate registrationDate = owner.getRegistrationDate();
285	        if (registrationDate == null) {
286	            return;
287	        }
288	        LocalDate today = LocalDate.now();
289	        if (registrationDate.isAfter(today)) {
290	            throw new FutureRegistrationDateException(registrationDate, today);
291	        }
292	    }
293	
294	    @Override
295	    @Transactional
296	    public void saveOwner(Owner owner) throws DataAccessException {
297	        assertPostcodeValid(owner);
298	        assertRegistrationDateNotFuture(owner);
299	        if (owner.getTelephone() != null) {
300	            owner.setTelephone(normalizeTelephone(owner.getTelephone()));
301	        }
302	        if (owner.getEmail() != null) {
303	            owner.setEmail(normalizeEmail(owner.getEmail()));
304	        }
305	        if (owner.getAddress() != null) {
306	            owner.setAddress(normalizeAddress(owner.getAddress()));
307	        }
308	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
309	        owner.setRegistrationDate(rollToBusinessDay(effectiveDate));
310	        if (owner.getCustomerCode() == null) {
311	            owner.setCustomerCode(generateCustomerCode(owner));
312	        }
313	        boolean creating = owner.isNew();
314	        if (creating) {
315	            owner.setNamesakeCount(countNamesakes(owner));
316	            assertDailyCapacity(owner);
317	            assertCityCapacity(owner);
318	        }
319	        assignHouseholdId(owner);
320	        assertIdentityUnique(owner);
321	        if (creating) {
322	            assertHouseholdUnique(owner);
323	        }
324	        ownerRepository.save(owner);
325	        populateHouseholdSize(owner);
326	        if (creating) {
327	            AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
328	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
329	                owner.getMembershipLevel());
330	        }
331	    }
332	
333	    /**
334	     * Build a {@code customerCode} formatted {@code '<REGION>-<HASH8>'} where REGION is the region
335	     * code derived from the owner's postcode (see {@link Region#regionForPostcode(String)}) and
336	     * HASH8 is the first 8 upper-case hex characters of the SHA-256 digest over the concatenation of
337	     * the owner's normalized telephone and {@code lastName}. The telephone is already normalized by
338	     * {@link #saveOwner(Owner)} before this runs. The {@code '<REGION>-<HASH8>'} layout is read back
339	     * by {@link Region#regionOfCustomerCode(String)}; keep the two in sync.
340	     */
341	    private String generateCustomerCode(Owner owner) {
342	        String region = Region.regionForPostcode(owner.getPostcode());
343	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
344	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
345	        String hash8 = sha256UpperHex(telephone + lastName, 8);
346	        return region + "-" + hash8;
347	    }
348	
349	    /**
350	     * The first {@code chars} upper-case hex characters of the SHA-256 digest of {@code value}'s
351	     * UTF-8 bytes.
352	     */
353	    private static String sha256UpperHex(String value, int chars) {
354	        try {
355	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
356	            byte[] hash = digest.digest(value.getBytes(StandardCharsets.UTF_8));
357	            StringBuilder sb = new StringBuilder(hash.length * 2);
358	            for (byte b : hash) {
359	                sb.append(String.format("%02X", b));
360	            }
361	            return sb.substring(0, chars);
362	        } catch (NoSuchAlgorithmException e) {
363	            throw new IllegalStateException("SHA-256 not available", e);
364	        }
365	    }
366	
367	    /** Maximum number of owners permitted in a single city. */
368	    private static final long CITY_OWNER_LIMIT = 50L;
369	
370	    /**
371	     * Rejects creating {@code owner} when its city already contains {@link #CITY_OWNER_LIMIT} or
372	     * more owners, so no city can grow beyond the capacity limit.
373	     *
374	     * @throws CityOwnerLimitException if the owner's city is already at capacity
375	     */
376	    private void assertCityCapacity(Owner owner) {
377	        if (owner.getCity() == null) {
378	            return;
379	        }
380	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
381	            throw new CityOwnerLimitException(owner.getCity(), CITY_OWNER_LIMIT);
382	        }
383	    }
384	
385	    /**
386	     * Rolls {@code date} forward to the next business day when it falls on a weekend: a Saturday or
387	     * Sunday becomes the following Monday. Business days (Monday to Friday) are returned unchanged.
388	     */
389	    private static LocalDate rollToBusinessDay(LocalDate date) {
390	        switch (date.getDayOfWeek()) {
391	            case SATURDAY:
392	                return date.plusDays(2);
393	            case SUNDAY:
394	                return date.plusDays(1);
395	            default:
396	                return date;
397	        }
398	    }
399	
400	    /** Maximum number of owners permitted to be registered on a single day. */
401	    private static final long DAILY_OWNER_LIMIT = 100L;
402	
403	    /** More than this many owners registered on a single day raises the bulk-signup warning. */
404	    private static final long BULK_SIGNUP_THRESHOLD = 80L;
405	
406	    /**
407	     * Reports whether more than {@link #BULK_SIGNUP_THRESHOLD} owners have already been registered
408	     * today, reusing the same daily accumulation as the per-day create limit ({@link
409	     * #assertDailyCapacity}).
410	     */
411	    @Override
412	    @Transactional(readOnly = true)
413	    public boolean isBulkSignupWarningActive() throws DataAccessException {
414	        return countOwnersRegisteredOn(LocalDate.now()) > BULK_SIGNUP_THRESHOLD;
415	    }
416	
417	    /**
418	     * Rejects creating {@code owner} when its {@code registrationDate} (defaulted to today for a new
419	     * owner) already has {@link #DAILY_OWNER_LIMIT} or more owners registered, so no more than that
420	     * many owners can be created on any single day.
421	     *
422	     * @throws DailyOwnerLimitException if the owner's registration day is already at capacity
423	     */
424	    private void assertDailyCapacity(Owner owner) {
425	        LocalDate date = owner.getRegistrationDate();
426	        if (date == null) {
427	            return;
428	        }
429	        if (countOwnersRegisteredOn(date) >= DAILY_OWNER_LIMIT) {
430	            throw new DailyOwnerLimitException(date, DAILY_OWNER_LIMIT);
431	        }
432	    }
433	
434	    private long countOwnersRegisteredOn(LocalDate date) {
435	        return ownerRepository.findAll().stream()
436	                .filter(existing -> date.equals(existing.getRegistrationDate()))
437	                .count();
438	    }
439	
440	    private long countOwnersInCity(String city) {
441	        String normalized = normalizeHouseholdValue(city);
442	        return ownerRepository.findAll().stream()
443	                .filter(existing -> normalized.equals(normalizeHouseholdValue(existing.getCity())))
444	                .count();
445	    }
446	
447	    /**
448	     * Counts the existing owners that share both {@code firstName} and {@code lastName} with the
449	     * given new {@code owner}, compared case-insensitively (with incidental whitespace collapsed).
450	     * The owner being created is not itself persisted yet, so the result is the number of namesakes
451	     * that already existed before this create.
452	     */
453	    private int countNamesakes(Owner owner) {
454	        String firstName = normalizeHouseholdValue(owner.getFirstName());
455	        String lastName = normalizeHouseholdValue(owner.getLastName());
456	        int count = 0;
457	        for (Owner existing : ownerRepository.findAll()) {
458	            if (!existing.getId().equals(owner.getId())
459	                    && firstName.equals(normalizeHouseholdValue(existing.getFirstName()))
460	                    && lastName.equals(normalizeHouseholdValue(existing.getLastName()))) {
461	                count++;
462	            }
463	        }
464	        return count;
465	    }
466	
467	    private static String normalizeEmail(String email) {
468	        return email == null ? null : email.toLowerCase(Locale.ROOT);
469	    }
470	
471	    /** Common street-type abbreviations expanded during address normalization. */
472	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
473	        "ST", "STREET",
474	        "RD", "ROAD",
475	        "AVE", "AVENUE");
476	
477	    /**
478	     * Canonicalizes a postal address: trims and collapses runs of whitespace into a single space,
479	     * upper-cases, and expands common street-type abbreviations (ST->STREET, RD->ROAD, AVE->AVENUE)
480	     * as whole words. Returns {@code null} for a {@code null} input and an empty string when the
481	     * address is blank once whitespace is stripped, so the required-field check sees the normalized
482	     * form.
483	     */
484	    private static String normalizeAddress(String address) {
485	        if (address == null) {
486	            return null;
487	        }
488	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
489	        if (collapsed.isEmpty()) {
490	            return "";
491	        }
492	        String[] tokens = collapsed.split(" ");
493	        StringBuilder sb = new StringBuilder(collapsed.length());
494	        for (int i = 0; i < tokens.length; i++) {
495	            if (i > 0) {
496	                sb.append(' ');
497	            }
498	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
499	        }
500	        return sb.toString();
501	    }
502	
503	    private static String normalizeTelephone(String telephone) {
504	        return telephone == null ? null : E164Telephone.toE164(telephone);
505	    }
506	
507	    /**
508	     * Rejects saving {@code owner} when its whole {@link Owner#getIdentityKey() identity key} equals
509	     * that of another owner. This single check consolidates the former separate telephone, email and
510	     * household duplicate rules: because the normalized telephone is part of the key, two members of
511	     * the same household (same {@code householdId}) with different telephones have different keys and
512	     * are both allowed — only an exact full-key match is a duplicate.
513	     *
514	     * @throws DuplicateIdentityException if another owner already has the same identity key
515	     */
516	    private void assertIdentityUnique(Owner owner) {
517	        String identityKey = owner.getIdentityKey();
518	        for (Owner existing : ownerRepository.findAll()) {
519	            if (!existing.getId().equals(owner.getId()) && identityKey.equals(existing.getIdentityKey())) {
520	                throw new DuplicateIdentityException(identityKey);
521	            }
522	        }
523	    }
524	
525	    /**
526	     * Assigns {@code owner} its deterministic {@code householdId}: the first 12 upper-case hex
527	     * characters of the SHA-256 digest over {@code normalizedLastName + '|' + postcode}, so all
528	     * owners that share a normalized {@code lastName} and {@code postcode} automatically share the
529	     * same household. Left {@code null} when either the lastName or the postcode is absent, since a
530	     * household is keyed on both.
531	     */
532	    private void assignHouseholdId(Owner owner) {
533	        String lastName = normalizeHouseholdValue(owner.getLastName());
534	        String postcode = owner.getPostcode();
535	        if (lastName.isEmpty() || postcode == null || postcode.isBlank()) {
536	            owner.setHouseholdId(null);
537	            return;
538	        }
539	        owner.setHouseholdId(generateHouseholdId(lastName, postcode));
540	    }
541	
542	    /**
543	     * Rejects creating {@code owner} when another owner already belongs to the same household — i.e.
544	     * shares its computed {@code householdId} (same normalized {@code lastName} and {@code postcode}).
545	     * Because the household is keyed on those two fields, a second such owner is a household
546	     * duplicate unless it declares {@code sharesHousehold}, in which case it is admitted as a
547	     * declared household member (and, being declared, is never a suspected duplicate). No-op when the
548	     * owner has no household id.
549	     *
550	     * @throws HouseholdDuplicateException if another owner already shares the household and the owner
551	     *     did not declare {@code sharesHousehold}
552	     */
553	    private void assertHouseholdUnique(Owner owner) {
554	        String householdId = owner.getHouseholdId();
555	        if (householdId == null || householdId.isBlank() || owner.isSharesHousehold()) {
556	            return;
557	        }
558	        for (Owner existing : ownerRepository.findAll()) {
559	            if (!existing.getId().equals(owner.getId()) && householdId.equals(existing.getHouseholdId())) {
560	                throw new HouseholdDuplicateException(householdId);
561	            }
562	        }
563	    }
564	
565	    /**
566	     * Stamps {@code owner} with the number of owners sharing its {@code householdId} (see {@link
567	     * Owner#getHouseholdSize()}), so presentation code can derive the membership tier without
568	     * reaching into the data store. A {@code null} owner or one without a household id is left at
569	     * size 0.
570	     */
571	    private void populateHouseholdSize(Owner owner) {
572	        if (owner == null) {
573	            return;
574	        }
575	        String householdId = owner.getHouseholdId();
576	        if (householdId == null || householdId.isBlank()) {
577	            owner.setHouseholdSize(0);
578	            return;
579	        }
580	        int count = 0;
581	        for (Owner existing : ownerRepository.findAll()) {
582	            if (householdId.equals(existing.getHouseholdId())) {
583	                count++;
584	            }
585	        }
586	        owner.setHouseholdSize(count);
587	    }
588	
589	    /**
590	     * Stamps every owner in {@code owners} with its household size in a single pass over the data
591	     * store, so a list/page of owners is counted without a per-owner query.
592	     *
593	     * @see #populateHouseholdSize(Owner)
594	     */
595	    private void populateHouseholdSizes(Collection<Owner> owners) {
596	        if (owners.isEmpty()) {
597	            return;
598	        }
599	        Map<String, Integer> sizes = new HashMap<>();
600	        for (Owner existing : ownerRepository.findAll()) {
601	            String householdId = existing.getHouseholdId();
602	            if (householdId != null && !householdId.isBlank()) {
603	                sizes.merge(householdId, 1, Integer::sum);
604	            }
605	        }
606	        for (Owner owner : owners) {
607	            String householdId = owner.getHouseholdId();
608	            owner.setHouseholdSize(householdId == null ? 0 : sizes.getOrDefault(householdId, 0));
609	        }
610	    }
