613	     * Derives the deterministic {@code householdId} from the normalized {@code lastName} and
614	     * {@code postcode}: the first 12 upper-case hex characters of SHA-256 over
615	     * {@code lastName + '|' + postcode}, so all owners in the same household share the same
616	     * identifier.
617	     */
618	    private static String generateHouseholdId(String lastName, String postcode) {
619	        return sha256UpperHex(lastName + "|" + postcode, 12);
620	    }
621	
622	    /**
623	     * Normalizes a household comparison value by trimming, collapsing runs of whitespace into a
624	     * single space and lower-casing, so comparisons ignore case and incidental whitespace.
625	     */
626	    private static String normalizeHouseholdValue(String value) {
627	        if (value == null) {
628	            return "";
629	        }
630	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
631	    }
632	
633	    @Override
634	    @Transactional(readOnly = true)
635	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
636	        Collection<Owner> owners = ownerRepository.findByLastName(lastName);
637	        populateHouseholdSizes(owners);
638	        return owners;
639	    }
